A key idea in our analysis is to use a recent upper bound for the convergence rate of cyclic incremental gradient method (see  \cite{Gur2015IncGrad}), which can be generalized to hold for any fixed deterministic order. This bound implies an almost sure upper bound (in fact one that holds for all sample paths) on the distance of the outer iterates $x_0^k$ generated by RR from the optimal solution $x^*$ denoted by
	$\dist_k  =\| x_0^k - x^*\|$
(see Section \ref{quad-conv}). Crucially, this result implies an upper bound in expected distance which is asymptotically $m$ times smaller than the almost sure guarantees on the distance of the iterates.

In analyzing RR, we will also consider the \textit{average} of the outer iterate sequence given by\footnote{It is well known that computing this (moving) average can be done efficiently in a dynamic manner by storing a vector of length $n$.} 
	$ \bar{x}_{k} := \frac{\sum_{j=0}^{k-1} x_0^j}{k}. \label{simple-average}
	$
 We also consider averaging only the most recent iterates, i.e. at iteration $k$, averaging the last $qk$ iterates
for some constant $q\in (0,1]$:
	$$\bar{x}_{q,k} := \frac{\sum_{j=(1-q)k }^{k-1} x_0^j}{qk}, \quad 0 < q\leq 1. $$ 
The generated sequence is referred to as the \textit{$q$-suffix average} of the sequence $x_0^k$. For SGD, it was shown that $q$-suffix averaging with $0<q<1$ leads to better performance then averaging (which corresponds to the $q=1$ case by definition), improving the convergence rate in the suboptimality of the function value from $\log k/k$ to $1/k$~\cite{Rakhlin:2011, Shamir:2012tj}. This is in line with our results in Section~\ref{sec:quad-case} which show faster rate for the $0<q<1$ case. The parameter $q$ can be thought as a measure of how much memory one uses during the averaging process. We define the \textit{$q$-suffix average} of the stepsize in a similar way:
 \beq \bar{\alpha}_{q,k} =\frac{\sum_{j=(1-q)k}^{k-1} \alpha_j}
{qk}, \quad 0<q\leq 1.\label{def-averaged-stepsize}
\eeq

\begin{theorem}\cite{Gur2015IncGrad} 
Let Assumption \ref{assump-sum-is-str-cvx} hold. Let $f_i(x)$ be a quadratic function of the form $f_i(x) = \frac{1}{2} x_i^T P_i x - q_i^T x + r_i$
where $P_i $ is a symmetric $n\times n$ matrix, $q_i \in \R^n$ is a column vector and $r_i$ is a scalar for $i=1,2,\dots,m$. Suppose Assumption \ref{assump-sum-is-str-cvx}  holds. Consider the iterates $\{x_0^k\}$ generated by the iterations \eqref{inner-update-wo} with a fixed order $\sigma$ and stepsize $\alpha_k = R/(k+1)^s$ where $R>0$ and  $s \in (1/2,1)$. Then\footnote{The original result in \cite{Gur2015IncGrad} was stated for $\sigma=\{1,2,\dots,m\}$ but here we translate this result into an arbitrary permutation $\sigma$ of $\{1,2,\dots,m\}$ by noting that processing the set of functions $\{f_1, f_2, \dots, f_m\}$ with order $\sigma$ is equivalent to processing the permuted functions $\{f_{\s_1}, f_{\s_2}, \dots, f_{\s_m}\}$ with order $\{1,2,\dots,m\}$.
},
         % \beq \dist_k \leq \frac{R \| \mu(\sigma)\| }{c}\frac{1}{k^s} + o(\frac{1}{k^s}) \quad \mbox{where} \quad  \mu(\sigma) =  \underset{1\leq i < j\leq m}{\sum} P_{\sigma(j)} \nabla f_{\sigma(i)}(x^*). %\label{def-Msigma}% \leq Lm \Gs
         % \eeq
    	\begin{align} \dist_k &\leq \frac{R \| \mu(\sigma)\| }{c}\frac{1}{k^s} + o(\frac{1}{k^s})  &\mbox{if}& \quad 1/2<s<1, \label{rate-prob-one-no-average}\\
           			  \dist_k  &\leq \frac{R^2 \|  \mu({\sigma}) \|}{ Rc - 1} \frac{1}{k} + o(\frac{1}{k})  &\mbox{if}& \quad s=1 \mbox{ and } Rc>1,
	  %\label{def-Msigma}% \leq Lm \Gs
    	\end{align}
where $c$ is the strong convexity constant of the sum function $f(x)$ and
\beq
	\mu(\sigma) =  - \underset{1\leq i < j\leq m}{\sum} P_{\sigma(j)} \nabla f_{\sigma(i)}(x^*). \label{def-Msigma}
\eeq  	
	\label{theo-rate-quadratics} 
\end{theorem}

